<script setup>
import {computed,ref,watch} from 'vue';
import SubaccountInput from './SubaccountInput.vue';
import {reportMoney as money,reportDate as date} from '../services/report-format.js';
import {decimal} from '../../../shared/money.js';
import {reconciliationSignedAmount} from '../../../shared/reconciliation-proposals.js';
const props=defineProps({row:Object,accounts:Array,busy:Boolean,canWrite:Boolean}),emit=defineEmits(['save','split','entry','invoice']);
const accountId=ref(''),remember=ref(false),pattern=ref(''),dirty=ref(false);let requestId=crypto.randomUUID();
const counterparts=computed(()=>props.row.proposal?.lines.filter(line=>line.account_id!==props.row.bank_account_id)||[]);
const multiple=computed(()=>counterparts.value.length>1);
function seed(){if(dirty.value)return;accountId.value=counterparts.value.length===1?String(counterparts.value[0].account_id):'';pattern.value=props.row.proposal?.rule_concept||props.row.concept.slice(0,200);}
watch(()=>props.row.proposal,seed,{immediate:true});
watch(()=>props.row.done,(value,previous)=>{if(previous&&!value){requestId=crypto.randomUUID();dirty.value=false;seed();}});
function changed(){dirty.value=true;requestId=crypto.randomUUID();}
const selected=computed(()=>props.accounts.find(row=>String(row.id)===String(accountId.value)));
const canSave=computed(()=>props.canWrite&&!props.busy&&!props.row.done&&!props.row.modified&&(multiple.value||selected.value)&&(!remember.value||pattern.value.trim().length>=3));
function value(){const amount=reconciliationSignedAmount(props.row.amount);return {movement_id:props.row.id,date:props.row.proposal?.date||props.row.date,concept:(props.row.proposal?.concept||props.row.concept).slice(0,200),remember:remember.value,rule_concept:pattern.value,request_id:requestId,counter_lines:multiple.value?counterparts.value.map(line=>({account_id:line.account_id,debit:line.debit,credit:line.credit})):[{account_id:Number(accountId.value),debit:amount<0n?decimal(-amount):'0.00',credit:amount>0n?decimal(amount):'0.00'}]};}
</script>
<template><tr :class="{'movement-done':row.done}"><td data-label="Data">{{ date(row.date) }}</td><td data-label="Concepte" class="movement-concept"><strong>{{ row.concept }}</strong><small v-if="row.proposal&&!row.done">{{ row.proposal.source==='history'?'Idea del teu diari':row.proposal.source==='saved_rule'?'Criteri recordat':row.proposal.source==='manual'?'Dades preparades':'Compte proposat' }}</small><details v-if="row.proposal?.source==='history'&&!row.done" class="history-idea"><summary>Veure precedent</summary><p>{{ row.proposal.basis }}</p></details><details v-if="row.invoices?.length" class="movement-invoices"><summary>{{ row.invoices.length===1?'Factura pendent relacionada':row.invoices.length+' possibles factures pendents' }}</summary><div v-for="candidate in row.invoices" :key="candidate.documentation_id"><span>{{ candidate.title }} · {{ money(candidate.total_amount) }} €</span><button class="button" :disabled="busy||!canWrite" @click="emit('invoice',candidate)">Passar a Factures</button></div></details></td><td data-label="Import" class="amount">{{ money(row.amount) }} €</td><td data-label="Compte / assentament" class="movement-account"><template v-if="row.done||row.modified"><button v-if="row.entry_id" class="button" @click="emit('entry',row.entry_id)">Assentament {{ row.entry_number }}</button><span v-else>Conciliat</span></template><template v-else><div v-if="multiple" class="movement-split"><p v-for="line in counterparts" :key="line.account_id">{{ line.code }} · {{ line.name }}<small>Deure {{ money(line.debit) }} · Haver {{ money(line.credit) }}</small></p></div><template v-else><SubaccountInput v-model="accountId" :accounts="accounts" :label="'Compte del moviment '+row.id" :disabled="busy||!canWrite" @update:model-value="changed"/><small>{{ selected?.description||'Posa el compte o busca’l amb la lupa' }}</small></template></template></td><td data-label="Recordar" class="movement-remember"><template v-if="!row.done&&!row.modified"><label class="remember-check"><input v-model="remember" type="checkbox" :disabled="busy||!canWrite" @change="changed">Recordar</label><input v-if="remember" v-model="pattern" :aria-label="'Concepte a recordar '+row.id" placeholder="Text que es repeteix" maxlength="200" :disabled="busy||!canWrite" @input="changed"></template><span v-else class="movement-saved">{{ row.modified?'Revisar':row.entry_id?'Guardat':'Conciliat' }}</span></td><td data-label="Acció" class="movement-actions"><template v-if="!row.done&&!row.modified"><button class="button primary" :disabled="!canSave" @click="emit('save',value())">Guardar assentament</button><button class="button" :disabled="busy||!canWrite" @click="emit('split',value())">Desglossar</button></template><button v-else-if="row.modified" class="button" @click="emit('entry',row.entry_id)">Revisar assentament</button></td></tr></template>
<style scoped>td{vertical-align:top}.movement-concept{max-width:310px;min-width:180px;overflow-wrap:anywhere}.movement-concept strong{font-weight:500}.movement-concept small,.movement-account>small,.movement-split small{display:block;color:#65748a;margin-top:7px;font-size:12px}.movement-account{min-width:230px}.movement-remember{min-width:175px;max-width:240px}.movement-remember>input{width:100%;font-size:12px;margin-top:10px}.remember-check{display:flex;flex-direction:row;align-items:center;gap:7px}.remember-check input{width:auto}.movement-actions .button{display:block;width:100%;margin-bottom:8px;white-space:nowrap}.movement-saved{color:#286944;font-weight:600}.movement-done{background:#f4faf6}.movement-split p{font-size:12px;margin:0 0 10px}.history-idea{font-size:12px;margin-top:8px}.history-idea summary{cursor:pointer;color:var(--primary)}.history-idea p{line-height:1.5;margin:8px 0}.movement-invoices{font-size:12px;margin-top:10px}.movement-invoices summary{cursor:pointer;color:var(--primary)}.movement-invoices div{display:grid;gap:8px;margin:10px 0}.amount{white-space:nowrap;text-align:right}@media(max-width:850px){tr{display:block;border:1px solid #dce4ee;border-radius:8px;margin:12px 0;padding:12px}td{display:block;border:0;padding:8px 0;max-width:none;min-width:0;text-align:left}td:before{content:attr(data-label);display:block;font-size:11px;font-weight:600;color:#65748a;margin-bottom:7px}td.amount{text-align:left}td:empty{display:none}.movement-account,.movement-remember{min-width:0;max-width:none}.movement-actions{display:flex;gap:8px;flex-wrap:wrap}.movement-actions:before{width:100%}.movement-actions .button{width:auto;white-space:normal;margin:0}}</style>
